alter table public.submittal_compliance_library add constraint compliance_library_id_tenant_unique unique(id,tenant_id); alter table public.submittal_compliance_library add constraint compliance_library_parent_tenant foreign key(parent_id,tenant_id) references public.submittal_compliance_library(id,tenant_id); drop policy compliance_library_save on public.submittal_compliance_library; create policy compliance_library_save on public.submittal_compliance_library for insert to authenticated with check (created_by=(select auth.uid()) and exists(select 1 from public.profiles p where p.user_id=(select auth.uid()) and p.tenant_id=submittal_compliance_library.tenant_id and p.is_approved=true));
